            new string[] { @"HUNTRESS: “Duck.”", @"SCOUT: “Huh? Look, if you wanna see me run, you just gotta...”", @"SCOUT: “HEY! Watch the head!”", @"HUNTRESS: “There was one behind you.”", @"SCOUT: “...Yeah, well. I saw it.”", @"HUNTRESS: “Are you hurt?”", @"SCOUT: “Me?! Ha! Not a scratch! That thing never even touched me!”", @"HUNTRESS: “Did you come from a ship?”", @"SCOUT: “Sure! Well... technically, yeah. The transport part was a disaster, though.”", @"HUNTRESS: “The Contact Light?”", @"SCOUT: “The what? No, no. I came here for a job!”", @"HUNTRESS: “I see.”", @"SCOUT: “Hey! I’m Scout! Fastest guy you’ll ever meet!”", @"HUNTRESS: “Huntress.”", @"SCOUT: “Huntress, huh? Nice! You a professional hunter or somethin’?”", @"HUNTRESS: “Yes.”", @"SCOUT: “Perfect! Because you just met another pro!”", @"HUNTRESS: “I can see that.”" },
            new string[] { @"SCOUT: “Come on! Little race! I take the middle, you go around!”", @"HUNTRESS: “We are not racing.”", @"SCOUT: “That’s what people say when they know they’ll lose!”", @"HUNTRESS: “That ground isn’t safe.”", @"SCOUT: “Ha! I’m too fast for anything to happen!”", @"SCOUT: “That doesn’t count! The course is rigged!”", @"HUNTRESS: “Don’t move.”", @"HUNTRESS: “Can you walk?”", @"SCOUT: “Of course! Just testing the natural defenses!”", @"HUNTRESS: “Then let’s go.”", @"SCOUT: “Think fast, chucklenuts!”", @"HUNTRESS: “I saw it too late.”", @"SCOUT: “Ha! Now are you impressed?”", @"HUNTRESS: “You are fast.”", @"SCOUT: “Fast?! I’m the fastest guy you’ll ever meet!”", @"HUNTRESS: “And the loudest.”", @"SCOUT: “...Hey! That counts as two records!”" },
            new string[] { @"SCOUT: “Wait. There are people inside?”", @"HUNTRESS: “Looks that way.”", @"SCOUT: “Then what are we waiting for?”", @"HUNTRESS: “We need to check the entrances. We don’t know how many creatures are there.”", @"SCOUT: “We’ll count ’em while we run!”", @"HUNTRESS: “Scout.”", @"SCOUT: “What? We can’t leave them!”", @"HUNTRESS: “We won’t. Follow me.”", @"HUNTRESS: “Get to that panel. I’ll cover the courtyard.”", @"SCOUT: “You want me to run across all that while they shoot at me?”", @"HUNTRESS: “I thought you were the fastest.”", @"SCOUT: “Ha! Knew you were impressed!”", @"HUNTRESS: “The panel is on the far side.”", @"SCOUT: “Don’t blink!”" },
            new string[] { @"SCOUT: “What do you mean somebody’s missing?!”", @"HUNTRESS: “We need to find her.”", @"SCOUT: “I’m going in!”", @"HUNTRESS: “Wait. I’m coming with you.”", @"SCOUT: “Come on! Move, you piece of junk!”", @"HUNTRESS: “Step aside.”", @"SCOUT: “Come on, lady! Luxury transport, courtesy of the fastest guy on the planet!”", @"SCOUT: “HEY! HEY! WE’RE STILL HERE!”", @"HUNTRESS: “They can’t stop. Too many creatures.”", @"SCOUT: “MEDIC! DOC! SOMEBODY TELL THEM TO COME BACK!”", @"HUNTRESS: “Scout, help me with her.”", @"SCOUT: “Great. Fantastic. Save everybody and get left behind. Again.”", @"HUNTRESS: “You went back for someone who couldn’t escape alone.”", @"SCOUT: “Well, yeah! What was I supposed to do, leave her there?”", @"HUNTRESS: “Not everyone would have gone back.”", @"SCOUT: “...Yeah, well. I’m pretty amazing.”" },
            new string[] { @"SCOUT: “So, what’s next? Another race? More monsters? Something to break?”", @"HUNTRESS: “Somewhere safe.”", @"SCOUT: “Oh! Now that sounds good.”", @"HUNTRESS: “There is a camp. Our expedition’s captain established it.”", @"SCOUT: “A camp? With real food and beds?”", @"HUNTRESS: “I hope so.”", @"SCOUT: “Perfect! I’ve spent way too long sleeping where something tries to eat me!”", @"HUNTRESS: “The signals match. Follow that route to the entry post.”", @"SCOUT: “Ha! Knew it! Told you I’d find the way!”", @"HUNTRESS: “You spent twenty minutes running in circles.”", @"SCOUT: “Terrain reconnaissance! Totally different!”", @"HUNTRESS: “Of course.”", @"SCOUT: “Hey! You’re not coming?”", @"HUNTRESS: “I still have something to track.”", @"SCOUT: “Well, your loss! Bet I’ll be the first one there!”", @"HUNTRESS: “If you keep talking, maybe not.”", @"SCOUT: “HEY! HUNTRESS! WAS IT LEFT OR RIGHT?!”", @"HUNTRESS: “LEFT!”", @"SCOUT: “KNEW IT!”" },
        };
        internal static string GetHuntress(bool es) => Render(es ? HuntressEs : HuntressEn, es);
        internal static string GetScout(bool es) => Render(es ? ScoutEs : ScoutEn, es);
        private static string Render(string[] scenes, bool es)
        {
            var dialogue = es ? DialogEs : DialogEn;
            var sb = new StringBuilder();
            for (int i = 0; i < scenes.Length; i++)
            {
                if (i > 0) sb.Append("\n\n");
                sb.Append(scenes[i]);
                if (dialogue[i].Length != 0) sb.Append("\n\n");
                foreach (var line in dialogue[i]) sb.Append(line).Append("\n");
            }
            return sb.ToString().TrimEnd();
        }
    }
}
